/// Routes Native 2D direct and generic capability calls into the same modeless workspace.
///
/// Returns `None` when the capability belongs to another Editor surface so the shell can
/// continue through the existing [`crate::EditorApp`] MCP router.
pub fn handle_mcp_tool_call(
    &mut self,
    project: &ProjectRoot,
    manifest: &engine::AssetManifest,
    name: &str,
    arguments: Value,
) -> Option<Result<Value, AuthoringWindowMcpCallFailure>> {
    let permissions = mcp_authoring_permissions();
    let generic_verb = match name {
        AUTHORING_INSPECT_TOOL => Some(AuthoringVerb::Inspect),
        AUTHORING_VALIDATE_TOOL => Some(AuthoringVerb::Validate),
        AUTHORING_PREVIEW_TOOL => Some(AuthoringVerb::Preview),
        AUTHORING_APPLY_TOOL => Some(AuthoringVerb::Apply),
        _ => None,
    };
    if let Some(verb) = generic_verb {
        let Ok(input) = serde_json::from_value::<CapabilityInvokeInput>(arguments.clone())
        else {
            return None;
        };
        let registry = AuthoringCapabilityRegistry::builtin();
        let is_native_2d = registry
            .get(&input.capability)
            .is_some_and(|capability| capability.domain == AuthoringDomain::Native2d);
        if !is_native_2d {
            return None;
        }
        let plan = match AuthoringCapabilityMcpTools::with_registry(registry)
            .plan(verb, &permissions, input)
        {
            Ok(plan) => plan,
            Err(error) => {
                return Some(Err(AuthoringWindowMcpCallFailure::new(
                    error.code(),
                    error.to_string(),
                )));
            }
        };
        return Some(
            self.native_2d
                .handle_mcp_tool_call(
                    project,
                    manifest,
                    &plan.tool,
                    plan.arguments,
                    &permissions,
                )
                .map_err(|error| {
                    AuthoringWindowMcpCallFailure::new(error.code(), error.message())
                }),
        );
    }

    let registry = AuthoringCapabilityRegistry::builtin();
    let is_native_2d = registry.capabilities().any(|capability| {
        capability.id.as_str() == name && capability.domain == AuthoringDomain::Native2d
    });
    if !is_native_2d {
        return None;
    }
    Some(
        self.native_2d
            .handle_mcp_tool_call(project, manifest, name, arguments, &permissions)
            .map_err(|error| {
                AuthoringWindowMcpCallFailure::new(error.code(), error.message())
            }),
    )
}

